import{_ as n,a0 as i,w as m,s as d,I as a,x as o,a1 as l,A as s,ao as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"使用 smartmontools 查看硬盤的健康狀態 | LCTT x X-CMD","titleTemplate":false,"description":"使用 smartmontools 查看硬盤的健康狀態 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 smartmontools 查看硬盤的健康狀態 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 smartmontools 查看硬盤的健康狀態 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141017 How to check hard disk health on Linux using smartmontools","title":"使用 smartmontools 查看硬盤的健康狀態","tag":"201412","desc":""},"relativePath":"201412/20141017 How to check hard disk health on Linux using smartmontools.md","filePath":"[post].md"}'),p={name:"201412/20141017 How to check hard disk health on Linux using smartmontools.md"};function A(u,t,T,g,f,h){const r=i("Link");return m(),d("div",null,[t[24]||(t[24]=a("h1",{id:"使用-smartmontools-查看硬盤的健康狀態",tabindex:"-1"},[o("使用 smartmontools 查看硬盤的健康狀態 "),a("a",{class:"header-anchor",href:"#使用-smartmontools-查看硬盤的健康狀態","aria-label":"Permalink to “使用 smartmontools 查看硬盤的健康狀態”"},"​")],-1)),a("p",null,[t[2]||(t[2]=o("要説Linux用户最不願意看到的事情，莫過於在毫無警告的情況下發現硬盤崩潰了。諸如",-1)),l(r,{href:"http://xmodulo.com/create-software-raid1-array-mdadm-linux.html"},{default:s(()=>[...t[0]||(t[0]=[o("RAID",-1)])]),_:1}),t[3]||(t[3]=o("的",-1)),l(r,{href:"http://xmodulo.com/how-to-create-secure-incremental-offsite-backup-in-linux.html"},{default:s(()=>[...t[1]||(t[1]=[o("備份",-1)])]),_:1}),t[4]||(t[4]=o("和存儲技術可以在任何時候幫用户恢復數據，但為預防硬件突然崩潰造成數據丟失所花費的代價卻是相當可觀的，特別是在用户從來沒有提前考慮過在這些情況下的應對措施時。",-1))]),a("p",null,[t[6]||(t[6]=o("為了避免遇到這種困境，用户可以試用一款叫做",-1)),l(r,{href:"http://www.smartmontools.org/"},{default:s(()=>[...t[5]||(t[5]=[o("smartmontools",-1)])]),_:1}),t[7]||(t[7]=o("的軟件包程序，它通過使用自我監控(Self-Monitoring)、分析(Analysis)和報告(Reporting)三種技術（縮寫為S.M.A.R.T或SMART）來管理和監控存儲硬件。如今大部分的ATA/SATA、SCSI/SAS和固態硬盤都搭載內置的SMART系統。SMART的目的是監控硬盤的可靠性、預測磁盤故障和執行各種類型的磁盤自檢。smartmontools由smartctl和smartd兩部分工具程序組成，它們一起為Linux平台提供對磁盤退化和故障的高級警告。",-1))]),t[25]||(t[25]=e(`<p>這篇文章會描述Linux上smartmontools的安裝和配置方法。</p><h3 id="安裝smartmontools" tabindex="-1">安裝Smartmontools <a class="header-anchor" href="#安裝smartmontools" aria-label="Permalink to “安裝Smartmontools”">​</a></h3><p>由於smartmontools在大部分Linux發行版的基本軟件庫中都可用，所以安裝很方便。</p><h4 id="debian和其衍生版" tabindex="-1">Debian和其衍生版：#### <a class="header-anchor" href="#debian和其衍生版" aria-label="Permalink to “Debian和其衍生版：####”">​</a></h4><pre><code># aptitude install smartmontools 
</code></pre><h4 id="基於red-hat的發行版" tabindex="-1">基於Red Hat的發行版：#### <a class="header-anchor" href="#基於red-hat的發行版" aria-label="Permalink to “基於Red Hat的發行版：####”">​</a></h4><pre><code># yum install smartmontools
</code></pre><h3 id="使用smartctl檢測硬盤的健康狀況" tabindex="-1">使用Smartctl檢測硬盤的健康狀況 <a class="header-anchor" href="#使用smartctl檢測硬盤的健康狀況" aria-label="Permalink to “使用Smartctl檢測硬盤的健康狀況”">​</a></h3><p>首先，使用下面的命令列出和系統相連的硬盤：</p><pre><code># ls -l /dev | grep -E &#39;sd|hd&#39;
</code></pre><p>輸出結果和下圖類似：</p><p><img src="https://farm4.staticflickr.com/3953/15352881249_96c09f7ccc_o.png" alt=""></p><p>其中sdX代表分配給機器上對應硬盤上的設備名。</p><p>如果想要顯示出某個指定硬盤的信息（比如設備模式、S/N、固件版本、大小、ATA版本/修訂號、SMART功能的可用性和狀態）,在運行smartctl命令時添加&quot;--info&quot;選項，並按如下所示指定硬盤的設備名。</p><p>在本例中，選擇/dev/sda。</p><pre><code># smartctl --info /dev/sda 
</code></pre><p><img src="https://farm4.staticflickr.com/3928/15353873870_00a8dddf89_z.jpg" alt=""></p><p>儘管最開始可能不會注意到ATA(譯者注：硬盤接口技術)的版本信息，但當需要替換硬盤時它確實是最重要的因素之一。每一代ATA版本都保持向下兼容。例如，老的ATA-1或ATA-2設備可以正常工作在ATA-6和ATA-7接口上，但反過來就不行了。在設備版本和接口版本兩者不匹配的情況下，它們會按照兩者中版本較小的規範來運行。也就是説，在這種情況下，需要替換硬盤時，ATA-7硬盤是最安全的選擇。</p><p>可以通過這個命令來檢測某個硬盤的健康狀況：</p><pre><code># smartctl -s on -a /dev/sda 
</code></pre><p>在這個命令中，&quot;-s on&quot;標誌開啓指定設備上的SMART功能。如果/dev/sda上已開啓SMART支持，那就省略它。</p><p>硬盤的SMART信息包含很多部分。其中，&quot;READ SMART DATA&quot;部分顯示出硬盤的整體健康狀況。</p><pre><code>=== START OF READ SMART DATA SECTION ===
SMART overall-health self-assessment rest result: PASSED
</code></pre><p>這個測試的結果是PASSED或FAILED。後者表示即將出現硬件故障，所以需要開始備份這塊磁盤上的重要數據！</p>`,24)),a("p",null,[t[9]||(t[9]=o("下一個需要關注的地方是",-1)),l(r,{href:"http://en.wikipedia.org/wiki/S.M.A.R.T."},{default:s(()=>[...t[8]||(t[8]=[o("SMART屬性",-1)])]),_:1}),t[10]||(t[10]=o("表，如下所示。",-1))]),t[26]||(t[26]=e(`<p><img src="https://farm6.staticflickr.com/5612/15539511935_dd62f6c9ef_z.jpg" alt=""></p><p>基本上，SMART屬性表列出了製造商在硬盤中定義好的屬性值，以及這些屬性相關的故障閾值。這個表由驅動固件自動生成和更新。</p><ul><li><strong>ID</strong>：屬性ID，通常是一個1到255之間的十進制或十六進制的數字。</li><li><strong>ATTRIBUTE_NAME</strong>：硬盤製造商定義的屬性名。</li><li><strong>FLAG</strong>：屬性操作標誌（可以忽略）。</li><li><strong>VALUE</strong>：這是表格中最重要的信息之一，代表給定屬性的標準化值，在1到253之間。253意味着最好情況，1意味着最壞情況。取決於屬性和製造商，初始化VALUE可以被設置成100或200.</li><li><strong>WORST</strong>：所記錄的最小VALUE。</li><li><strong>THRESH</strong>：在報告硬盤FAILED狀態前，WORST可以允許的最小值。</li><li><strong>TYPE</strong>：屬性的類型（Pre-fail或Old_age）。Pre-fail類型的屬性可被看成一個關鍵屬性，表示參與磁盤的整體SMART健康評估（PASSED/FAILED）。如果任何Pre-fail類型的屬性故障，那麼可視為磁盤將要發生故障。另一方面，Old_age類型的屬性可被看成一個非關鍵的屬性（如正常的磁盤磨損），表示不會使磁盤本身發生故障。</li><li><strong>UPDATED</strong>：表示屬性的更新頻率。Offline代表磁盤上執行離線測試的時間。</li><li><strong>WHEN_FAILED</strong>：如果VALUE小於等於THRESH，會被設置成“FAILING_NOW”；如果WORST小於等於THRESH會被設置成“In_the_past”；如果都不是，會被設置成“-”。在“FAILING_NOW”情況下，需要儘快備份重要文件，特別是屬性是Pre-fail類型時。“In_the_past”代表屬性已經故障了，但在運行測試的時候沒問題。“-”代表這個屬性從沒故障過。</li><li><strong>RAW_VALUE</strong>：製造商定義的原始值，從VALUE派生。</li></ul><p>這時候你可能會想，“是的，smartctl看起來是個不錯的工具，但我更想知道如何避免手動運行的麻煩。”如果能夠以指定的間隔運行，同時又能通知我測試結果，那不是更好嗎？”</p><p>好消息是，這個功能已經有了。是smartd發揮作用的時候了！</p><h3 id="配置smartctl和smartd實現實時監控" tabindex="-1">配置Smartctl和Smartd實現實時監控 <a class="header-anchor" href="#配置smartctl和smartd實現實時監控" aria-label="Permalink to “配置Smartctl和Smartd實現實時監控”">​</a></h3><p>首先，編輯smartctl的配置文件(/etc/default/smartmontools)以便在系統啓動時啓動smartd，並以秒為單位指定間隔時間（如7200 = 2小時）。</p><pre><code>start_smartd=yes
smartd_opts=&quot;--interval=7200&quot;
</code></pre><p>下一步，編輯smartd的配置文件（/etc/smartd.conf），添加以下行內容。</p><pre><code>/dev/sda -m myemail@mydomain.com -M test
</code></pre><ul><li><strong>-m <code>&lt;email-address&gt;</code></strong>：指定發送測試報告到某個電子郵件地址。這裏可以是系統用户比如root，或者如果服務器已經配置成發送電子郵件到系統外部，則是類似於myemail@mydomain.com的郵件地址。</li><li><strong>-M <code>&lt;delvery-type&gt;</code></strong>：指定發送郵件報告的期望類型。 <ul><li><strong>once</strong>：為檢測到的每種磁盤問題只發送一封警告郵件。</li><li><strong>daily</strong>：為檢測到的每種磁盤問題每隔一天發送一封額外的警告提醒郵件。</li><li><strong>diminishing</strong>：為檢測到的每種問題發送一封額外的警告提醒郵件，開始是每隔一天，然後每隔兩天，每隔四天，以此類推。每個間隔是前一次間隔的2倍。</li><li><strong>test</strong>：只要smartd一啓動，立即發送一封測試郵件。</li><li><strong>exec PATH</strong>：取代默認的郵件命令，運行PATH路徑下的可執行文件。PATH必須指向一個可執行的二進制文件或腳本。當檢測到一個問題時，可以指定執行一個期望的動作（閃爍控制台、關閉系統等等）。</li></ul></li></ul><p>保存改動並重啓smartd。</p><p>smartd發送的郵件應該是這個樣子。</p><p><img src="https://farm6.staticflickr.com/5612/15539511945_b344814c74_o.png" alt=""></p><p>在上圖中，沒有檢測到錯誤。如果實際上檢測到了錯誤，那麼錯誤會出現在“下列警告/錯誤由smartd守護進程寫入日誌”這一行的下面。</p><p>最後，可以使用“-s”標誌和形如“T/MM/DD/d/HH”的正則表達式按照想要的調度方案執行測試，其中：</p><p>正則表達式中的T代表測試的類型：</p><ul><li>L：長測試</li><li>S：短測試</li><li>C：傳輸測試（僅限ATA）</li><li>O：離線測試（僅限ATA）</li></ul><p>其它的字符代表測試執行的日期和時間：</p><ul><li>MM是一年中的月份。</li><li>DD是一月中的天份。</li><li>HH是一天中的小時。</li><li>d是一個星期中的某天（從1=週一到7=週日）。</li><li>MM、DD和HH使用兩位十進制數字表示。</li></ul><p>在上述表達中的小圓點表示所有可能的值。形如&#39;(A|B|C)&#39;在圓括號裏的表達式表示三個可能值A、B和C中的任意一個。形如[1-5]在方括號中的表達式表示1到5的範圍（包含5）.</p><p>例如，想要在每個工作日的下午一點為所有的磁盤執行一次長測試，在/etc/smartd.conf中添加如下行內容。確保編輯完重啓smartd。</p><pre><code>DEVICESCAN -s (L/../../[1-5]/13) 
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>無論你想要快速查看磁盤的電子和機械性能，還是對整個磁盤執行一次長時間掃描測試，都不要讓自己陷入日復一日地執行命令中而忘記了定期檢測磁盤的健康狀態。多關注磁盤的健康狀況，你會受益的！</p><hr>`,26)),a("p",null,[t[12]||(t[12]=o("via: ",-1)),l(r,{href:"http://xmodulo.com/check-hard-disk-health-linux-smartmontools.html"},{default:s(()=>[...t[11]||(t[11]=[o("http://xmodulo.com/check-hard-disk-health-linux-smartmontools.html",-1)])]),_:1})]),a("p",null,[t[16]||(t[16]=o("作者：",-1)),l(r,{href:"http://xmodulo.com/author/gabriel"},{default:s(()=>[...t[13]||(t[13]=[o("Gabriel Cánepa",-1)])]),_:1}),t[17]||(t[17]=o(" 譯者：",-1)),l(r,{href:"https://github.com/KayGuoWhu"},{default:s(()=>[...t[14]||(t[14]=[o("KayGuoWhu",-1)])]),_:1}),t[18]||(t[18]=o(" 校對：",-1)),l(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[15]||(t[15]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[21]||(t[21]=o("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原創翻譯，",-1)),l(r,{href:"http://linux.cn/"},{default:s(()=>[...t[20]||(t[20]=[o("Linux中國",-1)])]),_:1}),t[23]||(t[23]=o(" 榮譽推出",-1))])])}const D=n(p,[["render",A]]);export{L as __pageData,D as default};
